import{_ as a,o,c as i,ag as t}from"./chunks/framework.DC2anBTf.js";const p=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1793536832000}'),r={name:"guide/faq.md"};function d(n,e,c,l,u,s){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="redirect-参数在-web-端出现双重编码-252f" tabindex="-1">redirect 参数在 Web 端出现双重编码（<code>%252F</code>）？ <a class="header-anchor" href="#redirect-参数在-web-端出现双重编码-252f" aria-label="Permalink to &quot;redirect 参数在 Web 端出现双重编码（`%252F`）？&quot;">​</a></h2><p>已知行为。round-trip 正常（守卫登记与回跳还原一致）；深链场景上 Android 前建议实测确认。</p><h2 id="控制台出现-navigationfailure-日志" tabindex="-1">控制台出现 <code>NavigationFailure</code> 日志？ <a class="header-anchor" href="#控制台出现-navigationfailure-日志" aria-label="Permalink to &quot;控制台出现 `NavigationFailure` 日志？&quot;">​</a></h2><p>ux-router Web 端已知行为（relaunch 后的确认日志），跳转结果正确，<strong>不作为错误处理</strong>。</p><h2 id="为什么状态管理不用标准-pinia" tabindex="-1">为什么状态管理不用标准 Pinia？ <a class="header-anchor" href="#为什么状态管理不用标准-pinia" aria-label="Permalink to &quot;为什么状态管理不用标准 Pinia？&quot;">​</a></h2><p>uni-app x 的 App 端（Kotlin）不支持标准 Pinia 的插件协议（<code>app.use</code> 实测不生效），且 UTS 无 Proxy / 无反射，标准 Pinia 的响应式模型无法实现。ux-pinia 以 class + reactive 架构在 UTS 内实现了 Pinia 风格 API（详见 <a href="https://mengxi-studio.github.io/unix-pinia/" target="_blank" rel="noreferrer">unix-pinia 文档</a>的「与标准 Pinia 的差异」章节）。</p><h2 id="为什么-token-不用-ux-pinia-的内置持久化插件" tabindex="-1">为什么 token 不用 ux-pinia 的内置持久化插件？ <a class="header-anchor" href="#为什么-token-不用-ux-pinia-的内置持久化插件" aria-label="Permalink to &quot;为什么 token 不用 ux-pinia 的内置持久化插件？&quot;">​</a></h2><p>职责分离：token 读写收敛在 <code>utils/auth.uts</code>（对标 js-cookie 职责），<code>ensureAuthReady()</code> 消除冷启动竞态的设计已全链路验证；内置持久化默认后端为 uni storage，与 ux-storage 双轨并存会造成持久化语义分裂。内置持久化留给业务状态场景（如草稿箱）。</p><h2 id="ux-storage-是异步的-为什么读-token-是同步的" tabindex="-1">ux-storage 是异步的，为什么读 token 是同步的？ <a class="header-anchor" href="#ux-storage-是异步的-为什么读-token-是同步的" aria-label="Permalink to &quot;ux-storage 是异步的，为什么读 token 是同步的？&quot;">​</a></h2><p>内存缓存抹平：写入时「内存即时生效 + 异步落盘」，冷启动由守卫链首行 <code>await ensureAuthReady()</code> 一次性恢复内存缓存（Promise 复用，无竞态）。详见<a href="./auth.html">鉴权与守卫</a>。</p><h2 id="发行打包-云打包-发行到-web-报错-但-dev-运行正常" tabindex="-1">发行打包（云打包 / 发行到 Web）报错，但 dev 运行正常？ <a class="header-anchor" href="#发行打包-云打包-发行到-web-报错-但-dev-运行正常" aria-label="Permalink to &quot;发行打包（云打包 / 发行到 Web）报错，但 dev 运行正常？&quot;">​</a></h2><p>发行流水线与 dev 的差异导致的坑已在模板内修复（5.34 实测）：</p><ul><li>uts 插件入口<strong>不得导出字符串常量</strong>（uts-proxy 生成非法 JS）；</li><li>域类型必须在 <code>&lt;域&gt;/types.uts</code> 单文件内定义（发行拷贝不追踪 <code>export type ... from</code> 转发链）；</li><li>插件组件内避免 <code>Animation</code> 类型标注、<code>slots.default</code> 脚本级检查、带 <code>flush</code> 的 watch（5.34 Kotlin 生成器 Unresolved）。</li></ul><p>详见仓库 CHANGELOG 1.1.0 的 Fixed 章节。</p><h2 id="android-端连接不上本地-mock" tabindex="-1">Android 端连接不上本地 mock？ <a class="header-anchor" href="#android-端连接不上本地-mock" aria-label="Permalink to &quot;Android 端连接不上本地 mock？&quot;">​</a></h2><p><code>127.0.0.1</code> 在真机上指向手机自身。将 <code>config/index.uts</code> 的 <code>baseURL</code> 改为电脑局域网 IP（如 <code>http://192.168.x.x:3210</code>），保证手机与电脑同网，且 mock 服务监听 <code>0.0.0.0</code>。</p><h2 id="新页面跳转后守卫没生效" tabindex="-1">新页面跳转后守卫没生效？ <a class="header-anchor" href="#新页面跳转后守卫没生效" aria-label="Permalink to &quot;新页面跳转后守卫没生效？&quot;">​</a></h2><p>确认两点：页面声明了 <code>defineUniPage({ name, title })</code> 宏（路由表由插件生成）；跳转走的是 <code>useRouter()</code> 而非 <code>uni.navigateTo</code> 系（后者会被 InterceptorPlugin 兜底拦截，但不得依赖兜底）。</p><h2 id="hbuilderx-版本有要求吗" tabindex="-1">HBuilderX 版本有要求吗？ <a class="header-anchor" href="#hbuilderx-版本有要求吗" aria-label="Permalink to &quot;HBuilderX 版本有要求吗？&quot;">​</a></h2><p>模板在 <strong>5.34</strong> 完成编译与打包验证（Web + Android 云打包）。更早版本未验证；更高版本需关注 UTS 编译器的行为变化。</p>',21)])])}const x=a(r,[["render",d]]);export{p as __pageData,x as default};
